from fractions import Fraction
from collections import deque

def check_consistency_and_propagate(initial_assignments):
    """
    Checks consistency and propagates constraints based on given initial values 
    for f(q) in F_2.
    """
    f = {}
    for q, val in initial_assignments.items():
        f[q] = val

    queue = deque(f.keys())

    # To manage the search space, we only check the relations between pairs 
    # (r, r') that are required by the problem statement.

    while queue:
        r = queue.popleft()

        # 1. r' = -r
        r_neg = -r
        if r_neg != r:
            if r_neg not in f:
                # Propagate: f(r) + f(-r) = 1 => f(-r) = 1 - f(r)
                f[r_neg] = 1 - f[r]
                queue.append(r_neg)
            elif f[r_neg] != 1 - f[r]:
                return f, "Contradiction found for r' = -r"

        # 2. r' = 1 - r
        r_one_minus = 1 - r
        if r_one_minus != r:
            if r_one_minus not in f:
                # Propagate: f(r) + f(1-r) = 1 => f(1-r) = 1 - f(r)
                f[r_one_minus] = 1 - f[r]
                queue.append(r_one_minus)
            elif f[r_one_minus] != 1 - f[r]:
                return f, "Contradiction found for r' = 1 - r"

        # 3. r' = 1/r
        if r != 0:
            r_inv = 1 / r
            if r_inv != r:
                if r_inv not in f:
                    # Propagate: f(r) + f(1/r) = 1 => f(1/r) = 1 - f(r)
                    f[r_inv] = 1 - f[r]
                    queue.append(r_inv)
                elif f[r_inv] != 1 - f[r]:
                    return f, "Contradiction found for r' = 1/r"

    # Additional checks for consistency between already known values
    # Since we only used propagation from the queue, we must check all pairs 
    # that are now in f and satisfy the constraints.

    known_rationals = list(f.keys())
    N = len(known_rationals)

    for i in range(N):
        for j in range(i + 1, N):
            r = known_rationals[i]
            r_prime = known_rationals[j]

            # Check constraint 1: r + r' = 0
            if r + r_prime == 0:
                if f[r] + f[r_prime] != 1:
                    return f, f"Contradiction found for constraint r+r'=0: f({r}) + f({r_prime}) = {f[r]} + {f[r_prime]} != 1"

            # Check constraint 2: r + r' = 1
            if r + r_prime == 1:
                if f[r] + f[r_prime] != 1:
                    return f, f"Contradiction found for constraint r+r'=1: f({r}) + f({r_prime}) = {f[r]} + {f[r_prime]} != 1"

            # Check constraint 3: r * r' = 1
            if r * r_prime == 1:
                if f[r] + f[r_prime] != 1:
                    return f, f"Contradiction found for constraint r*r'=1: f({r}) + f({r_prime}) = {f[r]} + {f[r_prime]} != 1"

    return f, "Success"

